using CampusOps.Kata;

// Ported from tests/CampusOps.Infrastructure.Tests/Inventory/ConcurrentReservationTests.cs. The race test runs many
// short rounds of real threads, each competing for the LAST unit in stock. Every contender is already running
// (yield-spinning on one flag) before any is released, so their calls overlap; a kernel-event gate wakes them
// one by one and lets most rounds serialize. Rounds are capped by count AND wall time (runner timeout).
public sealed class PartReservationTests
{
    [Fact(DisplayName = "competing reservations for the last unit: exactly one caller wins and stock matches history (docs/quality/BUG-HARVEST.md:5)")]
    public async Task CompetingReservations_NeverOversell()
    {
        const int Rounds = 300;
        const int Contenders = 4;
        var deadline = Environment.TickCount64 + 20_000;
        for (var round = 0; round < Rounds && Environment.TickCount64 < deadline; round++)
        {
            var store = new InMemoryPartStore();
            var part = new Part(Guid.NewGuid(), "FLT-9", "Filter", 1);
            await store.AddAsync(part, default);
            var workOrderId = Guid.NewGuid();
            var results = new PartReservation?[Contenders];
            var ready = 0;
            var go = 0;
            var threads = Enumerable.Range(0, Contenders).Select(i => new Thread(() =>
            {
                Interlocked.Increment(ref ready);
                while (Volatile.Read(ref go) == 0) Thread.Yield();
                results[i] = store.ReserveForWorkOrderAsync(workOrderId, part.Id, 1, DateTimeOffset.UnixEpoch, default).GetAwaiter().GetResult();
            })).ToArray();
            foreach (var thread in threads) thread.Start();
            while (Volatile.Read(ref ready) < Contenders) Thread.Yield();
            Volatile.Write(ref go, 1);
            foreach (var thread in threads) Assert.True(thread.Join(TimeSpan.FromSeconds(10)), $"round {round}: a reservation thread did not finish");

            var stored = (await store.GetAsync(part.Id, default))!;
            var history = await store.ListForWorkOrderAsync(workOrderId, default);
            var winners = results.Count(r => r is not null);
            Assert.True(winners == 1, $"round {round}: {winners} callers were told they reserved the single unit in stock");
            Assert.Equal(history.Sum(x => x.Quantity), stored.Reserved);
            Assert.Equal(0, stored.Available);
        }
    }

    [Fact(DisplayName = "a cancelled reservation changes neither stock nor history")]
    public async Task CancelledReservationChangesNeitherStockNorHistory()
    {
        var store = new InMemoryPartStore();
        var part = new Part(Guid.NewGuid(), "F", "Filter", 5);
        var order = Guid.NewGuid();
        await store.AddAsync(part, default);
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => store.ReserveForWorkOrderAsync(order, part.Id, 2, DateTimeOffset.UtcNow, cancellation.Token));
        Assert.Equal(5, (await store.GetAsync(part.Id, default))!.Available);
        Assert.Empty(await store.ListForWorkOrderAsync(order, default));
    }

    [Fact(DisplayName = "insufficient stock returns null and appends no history")]
    public async Task InsufficientStockDoesNotAppendHistory()
    {
        var store = new InMemoryPartStore();
        var part = new Part(Guid.NewGuid(), "F", "Filter", 1);
        var order = Guid.NewGuid();
        await store.AddAsync(part, default);

        Assert.Null(await store.ReserveForWorkOrderAsync(order, part.Id, 2, DateTimeOffset.UtcNow, default));
        Assert.Equal(1, (await store.GetAsync(part.Id, default))!.Available);
        Assert.Empty(await store.ListForWorkOrderAsync(order, default));
    }

    [Fact(DisplayName = "a successful reservation commits stock and history together; the caller's object is not the stored aggregate")]
    public async Task ReservationCommitsStockAndHistory()
    {
        var store = new InMemoryPartStore();
        var part = new Part(Guid.NewGuid(), "F", "Filter", 5);
        var order = Guid.NewGuid();
        await store.AddAsync(part, default);

        var reservation = await store.ReserveForWorkOrderAsync(order, part.Id, 2, DateTimeOffset.UtcNow, default);

        Assert.NotNull(reservation);
        Assert.Equal(3, (await store.GetAsync(part.Id, default))!.Available);
        Assert.Equal(2, Assert.Single(await store.ListForWorkOrderAsync(order, default)).Quantity);
        Assert.Equal(5, part.Available);
    }
}

