using CampusOps.Kata;

// Ported from tests/CampusOps.Core.Tests/ServiceLevels/ServiceLevelTests.cs with fixed instants
// (astraupskill/advanced/extended-course/12-service-level-time-and-pause-accounting.md: deadline 11:00, pause 10:30, resume 12:00 -> 12:30).
public sealed class ServiceLevelTests
{
    private static readonly DateTimeOffset Day = new(2026, 9, 1, 0, 0, 0, TimeSpan.Zero);
    private static DateTimeOffset At(int hour, int minute = 0) => Day.AddHours(hour).AddMinutes(minute);

    private sealed class FixedClock(DateTimeOffset now) : IClock { public DateTimeOffset UtcNow { get; } = now; }

    private sealed class Store(params WorkOrderServiceLevel[] items) : IServiceLevelStore
    {
        public Task AddAsync(WorkOrderServiceLevel item, CancellationToken token) => Task.CompletedTask;
        public Task<IReadOnlyCollection<WorkOrderServiceLevel>> ListAsync(CancellationToken token) => Task.FromResult<IReadOnlyCollection<WorkOrderServiceLevel>>(items);
    }

    [Fact(DisplayName = "paused time extends the due date and a paused clock never escalates")]
    public void PausedTime_ExtendsDueDateAndPreventsEscalation()
    {
        var sla = new WorkOrderServiceLevel(Guid.NewGuid(), At(11));
        sla.Pause(At(10, 30));

        Assert.False(sla.EscalateIfOverdue(At(13)));
        Assert.Null(sla.EscalatedAt);

        sla.Resume(At(12));
        Assert.Equal(At(12, 30), sla.DueAt);
    }

    [Fact(DisplayName = "after resume the EXTENDED deadline governs: not overdue at 12:15, escalated once after 12:30")]
    public void AfterResume_ExtendedDeadlineGoverns()
    {
        var sla = new WorkOrderServiceLevel(Guid.NewGuid(), At(11));
        sla.Pause(At(10, 30));
        Assert.False(sla.EscalateIfOverdue(At(11, 30)));
        sla.Resume(At(12));

        Assert.False(sla.EscalateIfOverdue(At(12, 15)));
        Assert.True(sla.EscalateIfOverdue(At(12, 31)));
        Assert.Equal(At(12, 31), sla.EscalatedAt);
        Assert.False(sla.EscalateIfOverdue(At(13)));
    }

    [Fact(DisplayName = "the deadline instant itself is not overdue")]
    public void DeadlineEquality_IsNotOverdue()
    {
        var sla = new WorkOrderServiceLevel(Guid.NewGuid(), At(11));

        Assert.False(sla.EscalateIfOverdue(At(11)));
        Assert.True(sla.EscalateIfOverdue(At(11).AddTicks(1)));
    }

    [Fact(DisplayName = "the sweep escalates only running, overdue clocks")]
    public async Task Sweep_SkipsPausedAndOnTimeClocks()
    {
        var overdue = new WorkOrderServiceLevel(Guid.NewGuid(), At(9));
        var paused = new WorkOrderServiceLevel(Guid.NewGuid(), At(9));
        paused.Pause(At(8));
        var onTime = new WorkOrderServiceLevel(Guid.NewGuid(), At(15));
        var service = new ServiceLevelService(new Store(overdue, paused, onTime), new FixedClock(At(10)));

        Assert.Equal(1, await service.EscalateOverdueAsync(default));
        Assert.NotNull(overdue.EscalatedAt);
        Assert.Null(paused.EscalatedAt);
    }
}
